/**
 * Cat 6 — Auto-link Precision under Prose (at scale).
 *
 * Extends Cat 10 (adversarial.ts, 22 hand-crafted edge cases) to N prose-heavy
 * page variants generated by applying injections from
 * `adversarial-injections.ts` to world-v1 base pages.
 *
 * FEATURE BOUNDARY — what is under test vs what is harness-owned:
 *
 *   UNDER TEST: gbrain's pure link extractor (`extractPageLinks` in
 *   gbrain/link-extraction) over prose content: markdown entity refs,
 *   bare dir/slug paths, code-fence + inline-code stripping, and link-type
 *   inference. No DB, no LLM, no embeddings — the run is fully hermetic.
 *
 *   Bare-prose-name linking ("Adam Lee has been a familiar figure…" becomes
 *   a link to people/adam-lee) is not something `extractPageLinks` does: it
 *   takes no entity list, consults `resolver.resolve` only for frontmatter
 *   (Cat 6 passes `{}`) and `resolveBasenameMatches` only for `[[wikilink]]`
 *   text. So `prose_only_mention` is excluded from the pure-extractor arm's
 *   variants and denominators and listed under `kinds_not_exercised`.
 *
 *   gbrain DOES link bare names, through a different entry point: the
 *   by-mention pass (`gbrain extract links --by-mention --source db`,
 *   src/core/by-mention.ts, since v0.42.0.0) builds a gazetteer from the
 *   brain's person and company pages and links each first mention of a
 *   known title. An earlier version of this header said gbrain had no such
 *   pass at all; that was wrong (coverage audit F3). The GAZETTEER ARM
 *   (`runGazetteerArm`, run by main()) imports the corpus's person and
 *   company pages plus the prose_only_mention variants into an in-memory
 *   PGLite brain, runs `runExtract(engine, ['links', '--by-mention',
 *   '--source', 'db'])`, and scores each variant's must_extract link
 *   (type `mentions` enforced) from the links table. As a control it first
 *   runs the ordinary links pass, which lacks the gazetteer; its recall on
 *   the same variants is recorded so the capability can be attributed to
 *   the by-mention pass.
 *
 * SCORING (audit retrieval-cats-04 / -14):
 *   `scoreGoldDelta` (adversarial-injections.ts) is the canonical scorer —
 *   it enforces `enforce_type` gold (ambiguous_role's works_at→mentions
 *   downgrade is a `mistyped` FAILURE, not a match). Precision is computed
 *   over the LABELED universe only:
 *
 *     precision = matched / (matched + mistyped + false_positives)
 *
 *   Base-corpus pages carry ~2-6 legitimate links each that the gold deltas
 *   do not label; the old denominator (ALL extracted links) capped a perfect
 *   extractor at ~0.2-0.4 "precision". Unlabeled extractions are ignored by
 *   precision/recall and surface only in the mean_links_per_page diagnostic.
 *   metrics.ts primitives (recallAtK & co.) are ranked-list metrics and do
 *   not model typed set-membership gold, hence the count ratios here.
 *
 * FALSE-POSITIVE REACHABILITY (audit retrieval-cats-06):
 *   Each substring_collision variant gets a runner-side near-miss trap
 *   appended: the forbidden slug (a REAL corpus entity never linked on the
 *   page) plus a suffix, as a bare path (`people/sam-jones-ai`). A correct
 *   extractor emits only the full path (unlabeled, ignored); a prefix/
 *   substring-truncation bug emits the forbidden slug itself — a scored FP.
 *   Two hermetic negative controls prove the FP plumbing can fire: a
 *   simulated no-code-stripping extractor must leak the fenced/inline fakes,
 *   and a simulated hyphen-truncating bare-path matcher must trip the
 *   substring trap. A control that does not fire invalidates the run.
 *
 * GATES (failable): see `GATES` below. verdict = 'pass' iff every gate
 * holds. Committed first baseline (world-v1, perKind 50, seed 1000, gbrain
 * v0.47.6.0, 5 scored kinds): recall 1.0, precision 1.0, type-match 1.0,
 * all leak/collision rates 0. Floors sit below 1.0 because the extractor's
 * type inference IS context-sensitive — other (seed, page) arrangements
 * measured 41/50 = 0.82 ambiguous_role type-match — and a regression gate
 * that fails on any single flipped variant would be noise, not signal.
 */

import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'fs';
import { basename, dirname, join, resolve } from 'path';
import {
  ALL_INJECTION_KINDS,
  applyInjection,
  scoreGoldDelta,
  type EntityRef,
  type GoldDelta,
  type InjectionKind,
} from './adversarial-injections.ts';
import { extractPageLinks, type SlugResolver } from 'gbrain/link-extraction';
import type { PageType } from 'gbrain/types';
import { ProbeAccounting, type ProbeSummary } from './probe-accounting.ts';
import {
  BENCHMARK_VERSION,
  RECEIPT_SCHEMA_VERSION,
  receiptPath,
  writeReceipt,
  type Receipt,
  noModelSpend,
} from './receipt.ts';
import { gbrainPin, gbrainVersion } from './gbrain-version.ts';

// ─── Scored kinds + boundary note ─────────────────────────────────────

export const PROSE_ONLY_BOUNDARY_NOTE =
  'prose_only_mention requires bare-prose-name linking, which the pure '
  + 'extractor under test here does not do (extractPageLinks emits candidates '
  + 'only for markdown refs, wikilinks, bare dir/slug paths, and frontmatter; '
  + 'it takes no entity list). The kind is excluded from this arm\'s '
  + 'generation and denominators (audit retrieval-cats-05) and scored instead '
  + 'by the gazetteer arm, which runs gbrain\'s by-mention extract pass over a '
  + 'PGLite brain (see gazetteer_arm in the receipt).';

/** Kinds whose gold the exercised pipeline can actually satisfy or violate. */
export const SCORED_INJECTION_KINDS: readonly InjectionKind[] =
  ALL_INJECTION_KINDS.filter(k => k !== 'prose_only_mention');

export interface KindNotExercised {
  kind: InjectionKind;
  reason: string;
}

export const KINDS_NOT_EXERCISED: readonly KindNotExercised[] = [
  { kind: 'prose_only_mention', reason: PROSE_ONLY_BOUNDARY_NOTE },
];

// ─── Gates ────────────────────────────────────────────────────────────

/**
 * Regression floors/ceilings against the committed first baseline
 * (world-v1, perKind 50, seed 1000, gbrain v0.47.6.0: link_recall 1.0,
 * link_precision 1.0, ambiguous_role type-match 1.0, all leak/collision
 * rates 0 — see the header for why the min floors sit below 1.0). A gate
 * value of null (metric not measurable in this run) fails the gate — an
 * unmeasurable gate must not pass silently.
 */
export const GATES = {
  code_fence_leak_rate_max: 0,
  inline_code_leak_rate_max: 0,
  substring_fp_rate_max: 0,
  link_recall_min: 0.95,
  link_precision_min: 0.95,
  ambiguous_role_type_match_min: 0.8,
} as const;

/**
 * Gazetteer-arm floors. First measurement (world-v1, 50 variants, seed 1000,
 * gbrain master b80cad6): recall 50/50, every link typed `mentions`.
 */
export const GAZETTEER_GATES = {
  prose_only_mention_gazetteer_recall_min: 0.95,
  prose_only_mention_gazetteer_type_match_min: 0.95,
} as const;

export interface GateResult {
  gate: string;
  value: number | null;
  bound: number;
  op: 'max' | 'min';
  pass: boolean;
}

// ─── Types ────────────────────────────────────────────────────────────

export interface VariantCase {
  /** Unique id for this variant, e.g. "people/alice-v0-code_fence_leak". */
  variantId: string;
  /** Base slug the variant was derived from. */
  baseSlug: string;
  baseType: PageType;
  /** Injection applied to the base content. */
  kind: InjectionKind;
  /** Transformed content (what the extractor sees). */
  content: string;
  /** Gold delta from the injection. */
  goldDelta: GoldDelta;
}

export interface ExtractedLink {
  targetSlug: string;
  linkType: string;
}

export interface VariantResult {
  variantId: string;
  kind: InjectionKind;
  extracted: ExtractedLink[];
  /** must_not_extract slugs that appeared in extraction output. */
  false_positives: Array<{ slug: string; reason: string }>;
  /** must_extract slugs that never appeared. */
  missed: Array<{ slug: string; type: string; reason: string }>;
  /** enforce_type musts whose slug appeared ONLY with a wrong type — a failure. */
  mistyped: Array<{ slug: string; expected_type: string; actual_types: string[]; reason: string }>;
  /** must_extract entries fully satisfied (slug present; type too when enforced). */
  matched: number;
  /** Set when extractPageLinks threw — the SUT failed the probe (scored miss). */
  sut_error?: string;
}

export interface VariantEvidenceRow extends VariantResult {
  probe_id: string;
  contributed: boolean;
  baseSlug: string;
  baseType: PageType;
  goldDelta: GoldDelta;
}

export function variantEvidence(variant: VariantCase, result: VariantResult): VariantEvidenceRow {
  return {
    ...result,
    probe_id: variant.variantId,
    contributed: true,
    baseSlug: variant.baseSlug,
    baseType: variant.baseType,
    goldDelta: variant.goldDelta,
  };
}

export interface PerKindReport {
  kind: InjectionKind;
  variants: number;
  total_must_extract: number;
  total_matched: number;
  total_mistyped: number;
  total_missed: number;
  total_must_not: number;
  total_false_positives: number;
  /** matched / (matched + mistyped + false_positives); null when no labeled predictions. */
  precision: number | null;
  /** matched / total_must_extract; null when the kind has no must_extract gold. */
  recall: number | null;
  /** matched / (matched + mistyped); null when the slug never appeared at all. */
  type_match_rate: number | null;
  /** false_positives / total_must_not; null when the kind has no must_not gold. */
  false_positive_rate: number | null;
}

export interface NegativeControlResult {
  control: string;
  description: string;
  /** Variants on which the simulated bug produced a scored false positive. */
  fired_on: number;
  variants: number;
  /** fired_on > 0 — the metric CAN fail. False invalidates the run. */
  fired: boolean;
}

export interface Cat6Report {
  schema_version: 2;
  ran_at: string;
  variants: number;
  corpus_id: string;
  per_kind: PerKindReport[];
  kinds_not_exercised: KindNotExercised[];
  overall: {
    link_precision: number | null;
    link_recall: number | null;
    link_f1: number | null;
    code_fence_leak_rate: number | null;
    inline_code_leak_rate: number | null;
    substring_fp_rate: number | null;
    ambiguous_role_type_match_rate: number | null;
    pages_with_links_coverage: number;
    /** Diagnostic only: counts ALL extracted links incl. unlabeled base-corpus links. */
    mean_links_per_page: number;
  };
  gates: GateResult[];
  negative_controls: NegativeControlResult[];
  verdict: 'pass' | 'fail';
  rows: VariantEvidenceRow[];
}

// ─── Corpus loading ──────────────────────────────────────────────────

export interface BasePage {
  slug: string;
  type: PageType;
  title: string;
  content: string;
}

/**
 * Minimal loader for `eval/data/world-v1` JSON shards. Each shard has shape
 * `{slug, type, title, compiled_truth, timeline, _facts}`. We concatenate
 * compiled_truth + timeline as the extractor sees them.
 */
export function loadWorldV1(
  corpusDir: string = resolve(process.cwd(), 'eval/data/world-v1'),
): BasePage[] {
  const files = readdirSync(corpusDir).filter(
    f => f.endsWith('.json') && !f.startsWith('_'),
  ).sort();
  const pages: BasePage[] = [];
  for (const f of files) {
    const raw = readFileSync(join(corpusDir, f), 'utf8');
    const shard = JSON.parse(raw) as {
      slug: string;
      type: PageType;
      title: string;
      compiled_truth: string;
      timeline?: string;
    };
    pages.push({
      slug: shard.slug,
      type: shard.type,
      title: shard.title,
      content: `${shard.compiled_truth}\n\n${shard.timeline ?? ''}`,
    });
  }
  return pages;
}

// ─── Variant generation ──────────────────────────────────────────────

function pagesToRefs(pages: BasePage[]): EntityRef[] {
  return pages
    .filter(p => p.type === 'person' || p.type === 'company')
    .map(p => ({ slug: p.slug, name: p.title }));
}

export interface VariantGenerationOpts {
  /** Max variants per injection kind. Default 50 → 50 × 5 scored kinds = 250. */
  perKind?: number;
  /** Seed offset; each variant computes seed = baseSeed + variantIdx. Default 1000. */
  baseSeed?: number;
  /** Optional set of base-page types to include. Default ['person', 'company']. */
  includeTypes?: PageType[];
  /** Injection kinds to generate. Default SCORED_INJECTION_KINDS (audit retrieval-cats-05). */
  kinds?: readonly InjectionKind[];
}

const NEAR_MISS_SUFFIXES = ['-ai', '-lab', '-hub', '-x'] as const;

/**
 * Substring near-miss trap (audit retrieval-cats-06): append the forbidden
 * slug + a suffix as a bare path. gbrain's bare-path pass matches the maximal
 * token, so a correct extractor emits only `<forbidden><suffix>` (unlabeled,
 * ignored) — while a prefix/substring-truncation bug emits `<forbidden>`
 * itself, which the gold's must_not_extract turns into a scored FP.
 */
function appendNearMissTrap(
  content: string,
  forbiddenSlug: string,
  knownSlugs: ReadonlySet<string>,
): string {
  const suffix =
    NEAR_MISS_SUFFIXES.find(s => !knownSlugs.has(`${forbiddenSlug}${s}`)) ?? '-trap';
  return `${content}\n\nDraft notes are parked at ${forbiddenSlug}${suffix} until the migration completes.`;
}

/**
 * Generate variant cases deterministically from a base corpus. Variants are
 * spread across the scored injection kinds; seed determinism means re-running
 * against the same corpus produces identical variants.
 */
export function generateVariants(
  pages: BasePage[],
  opts: VariantGenerationOpts = {},
): VariantCase[] {
  const perKind = opts.perKind ?? 50;
  const baseSeed = opts.baseSeed ?? 1000;
  const includeTypes = opts.includeTypes ?? (['person', 'company'] as PageType[]);
  const kinds = opts.kinds ?? SCORED_INJECTION_KINDS;
  const validPages = pages.filter(p => includeTypes.includes(p.type));
  if (validPages.length === 0) return [];

  const refs = pagesToRefs(pages);
  const knownSlugs = new Set(pages.map(p => p.slug));

  const variants: VariantCase[] = [];
  let variantIdx = 0;

  for (const kind of kinds) {
    for (let i = 0; i < perKind; i++) {
      // Deterministic base page pick: step through the corpus in order.
      const base = validPages[(variantIdx + i) % validPages.length];
      const seed = baseSeed + variantIdx;
      const res = applyInjection(kind, { content: base.content, seed, refs });
      let content = res.content;
      if (kind === 'substring_collision' && res.goldDelta.must_not_extract.length > 0) {
        content = appendNearMissTrap(
          content,
          res.goldDelta.must_not_extract[0].slug,
          knownSlugs,
        );
      }
      variants.push({
        variantId: `${base.slug}-v${i}-${kind}`,
        baseSlug: base.slug,
        baseType: base.type,
        kind,
        content,
        goldDelta: res.goldDelta,
      });
      variantIdx++;
    }
  }

  return variants;
}

// ─── Extraction + scoring ─────────────────────────────────────────────

/**
 * Corpus-membership resolver handed to extractPageLinks. Honesty note: the
 * prose/markdown candidate passes never consult a resolver — gbrain only
 * calls `resolve` for frontmatter fields (Cat 6 passes `{}`) and
 * `resolveBasenameMatches` for `[[wikilink]]` text (no injection produces
 * wikilinks). It exists to satisfy the extractPageLinks signature with
 * corpus-true semantics, not to filter prose candidates.
 */
export function makeCorpusResolver(pages: BasePage[]): SlugResolver {
  const known = new Set(pages.map(p => p.slug));
  return {
    resolve: async (name: string) => {
      if (known.has(name)) return name;
      return null;
    },
  };
}

async function extractOne(
  variant: VariantCase,
  resolver: SlugResolver,
): Promise<ExtractedLink[]> {
  const res = await extractPageLinks(
    variant.baseSlug,
    variant.content,
    {}, // frontmatter unused for Cat 6 prose tests
    variant.baseType,
    resolver,
  );
  return res.candidates
    .filter(c => c.targetSlug)
    .map(c => ({ targetSlug: c.targetSlug, linkType: c.linkType ?? 'mentions' }));
}

/**
 * Pure scoring: extraction output vs the variant's gold delta, via the
 * canonical `scoreGoldDelta` (enforce_type gold can FAIL on a wrong type —
 * audit retrieval-cats-14). Exported so tests can fault-inject extractions.
 */
export function scoreExtraction(
  variant: VariantCase,
  extracted: ExtractedLink[],
): VariantResult {
  const s = scoreGoldDelta(variant.goldDelta, extracted);
  return {
    variantId: variant.variantId,
    kind: variant.kind,
    extracted,
    false_positives: s.false_positives,
    missed: s.missed,
    mistyped: s.mistyped,
    matched: s.matched.length,
  };
}

export async function scoreVariant(
  variant: VariantCase,
  resolver: SlugResolver,
): Promise<VariantResult> {
  const extracted = await extractOne(variant, resolver);
  return scoreExtraction(variant, extracted);
}

// ─── Simulated-bug extractors (negative controls) ────────────────────

/**
 * Simulated regression: markdown + bare-path scan WITHOUT code stripping.
 * Must leak the fenced/inline fake slugs, or the leak metrics are decorative.
 */
export function noCodeStripExtraction(content: string): ExtractedLink[] {
  const out: ExtractedLink[] = [];
  const md = /\[[^\]]+\]\(((?:\.\.\/)*[a-z0-9][a-z0-9_-]*\/[^)\s]+?)(?:\.md)?\)/g;
  let m: RegExpExecArray | null;
  while ((m = md.exec(content)) !== null) {
    out.push({ targetSlug: m[1], linkType: 'mentions' });
  }
  const bare = /\b([a-z0-9][a-z0-9_-]*\/[a-z0-9][a-z0-9/-]*[a-z0-9])\b/g;
  while ((m = bare.exec(content)) !== null) {
    out.push({ targetSlug: m[1], linkType: 'mentions' });
  }
  return out;
}

/**
 * Simulated regression: a bare-path matcher that also emits every
 * hyphen-truncated prefix of each path (`people/sam-jones-ai` → also
 * `people/sam-jones`, `people/sam`). Must trip the substring near-miss trap.
 */
export function hyphenTruncatingExtraction(content: string): ExtractedLink[] {
  const out: ExtractedLink[] = [];
  const bare = /\b([a-z0-9][a-z0-9_-]*\/[a-z0-9][a-z0-9/-]*[a-z0-9])\b/g;
  let m: RegExpExecArray | null;
  while ((m = bare.exec(content)) !== null) {
    const path = m[1];
    out.push({ targetSlug: path, linkType: 'mentions' });
    const [dir, rest] = [path.slice(0, path.indexOf('/')), path.slice(path.indexOf('/') + 1)];
    const segs = rest.split('-');
    for (let i = 1; i < segs.length; i++) {
      out.push({ targetSlug: `${dir}/${segs.slice(0, i).join('-')}`, linkType: 'mentions' });
    }
  }
  return out;
}

export function runNegativeControls(variants: VariantCase[]): NegativeControlResult[] {
  const leakVariants = variants.filter(
    v => v.kind === 'code_fence_leak' || v.kind === 'inline_code_slug',
  );
  const leakFired = leakVariants.filter(
    v => scoreGoldDelta(v.goldDelta, noCodeStripExtraction(v.content)).false_positives.length > 0,
  ).length;
  const substrVariants = variants.filter(v => v.kind === 'substring_collision');
  const substrFired = substrVariants.filter(
    v => scoreGoldDelta(v.goldDelta, hyphenTruncatingExtraction(v.content)).false_positives.length > 0,
  ).length;
  const controls: NegativeControlResult[] = [];
  if (leakVariants.length > 0) {
    controls.push({
      control: 'code_leak_detectable',
      description:
        'a simulated no-code-stripping extractor must produce scored FPs on '
        + 'code_fence_leak / inline_code_slug variants',
      fired_on: leakFired,
      variants: leakVariants.length,
      fired: leakFired > 0,
    });
  }
  if (substrVariants.length > 0) {
    controls.push({
      control: 'substring_fp_detectable',
      description:
        'a simulated hyphen-truncating bare-path matcher must trip the '
        + 'substring_collision near-miss trap (audit retrieval-cats-06)',
      fired_on: substrFired,
      variants: substrVariants.length,
      fired: substrFired > 0,
    });
  }
  return controls;
}

// ─── Aggregation ──────────────────────────────────────────────────────

function ratio(num: number, den: number): number | null {
  return den === 0 ? null : num / den;
}

function f1(p: number | null, r: number | null): number | null {
  if (p === null || r === null) return null;
  if (p + r === 0) return 0;
  return (2 * p * r) / (p + r);
}

function evaluateGates(overall: Cat6Report['overall']): GateResult[] {
  const spec: Array<{ gate: string; value: number | null; bound: number; op: 'max' | 'min' }> = [
    { gate: 'code_fence_leak_rate', value: overall.code_fence_leak_rate, bound: GATES.code_fence_leak_rate_max, op: 'max' },
    { gate: 'inline_code_leak_rate', value: overall.inline_code_leak_rate, bound: GATES.inline_code_leak_rate_max, op: 'max' },
    { gate: 'substring_fp_rate', value: overall.substring_fp_rate, bound: GATES.substring_fp_rate_max, op: 'max' },
    { gate: 'link_recall', value: overall.link_recall, bound: GATES.link_recall_min, op: 'min' },
    { gate: 'link_precision', value: overall.link_precision, bound: GATES.link_precision_min, op: 'min' },
    { gate: 'ambiguous_role_type_match', value: overall.ambiguous_role_type_match_rate, bound: GATES.ambiguous_role_type_match_min, op: 'min' },
  ];
  return spec.map(({ gate, value, bound, op }) => ({
    gate,
    value,
    bound,
    op,
    // Unmeasurable (null) never passes: a gate that cannot be evaluated must
    // not read as green.
    pass: value !== null && (op === 'max' ? value <= bound : value >= bound),
  }));
}

export function aggregate(variants: VariantCase[], results: VariantResult[]): Cat6Report {
  if (variants.length !== results.length) {
    throw new Error(`aggregate: ${variants.length} variants but ${results.length} results`);
  }
  const byKind = new Map<InjectionKind, { variants: VariantCase[]; results: VariantResult[] }>();
  for (let i = 0; i < variants.length; i++) {
    const v = variants[i];
    const r = results[i];
    if (!byKind.has(v.kind)) byKind.set(v.kind, { variants: [], results: [] });
    byKind.get(v.kind)!.variants.push(v);
    byKind.get(v.kind)!.results.push(r);
  }

  const per_kind: PerKindReport[] = [];

  let totalMust = 0;
  let totalMatched = 0;
  let totalMistyped = 0;
  let totalFp = 0;
  let totalExtracted = 0;
  let variantsWithLinks = 0;

  for (const [kind, bucket] of byKind) {
    let kindMust = 0;
    let kindMustNot = 0;
    let kindMatched = 0;
    let kindMistyped = 0;
    let kindMissed = 0;
    let kindFp = 0;

    for (let i = 0; i < bucket.variants.length; i++) {
      const v = bucket.variants[i];
      const r = bucket.results[i];
      kindMust += v.goldDelta.must_extract.length;
      kindMustNot += v.goldDelta.must_not_extract.length;
      kindMatched += r.matched;
      kindMistyped += r.mistyped.length;
      kindMissed += r.missed.length;
      kindFp += r.false_positives.length;
      totalExtracted += r.extracted.length;
      if (r.extracted.length > 0) variantsWithLinks++;
    }

    per_kind.push({
      kind,
      variants: bucket.variants.length,
      total_must_extract: kindMust,
      total_matched: kindMatched,
      total_mistyped: kindMistyped,
      total_missed: kindMissed,
      total_must_not: kindMustNot,
      total_false_positives: kindFp,
      precision: ratio(kindMatched, kindMatched + kindMistyped + kindFp),
      recall: ratio(kindMatched, kindMust),
      type_match_rate: ratio(kindMatched, kindMatched + kindMistyped),
      false_positive_rate: ratio(kindFp, kindMustNot),
    });

    totalMust += kindMust;
    totalMatched += kindMatched;
    totalMistyped += kindMistyped;
    totalFp += kindFp;
  }

  const kindReport = (k: InjectionKind) => per_kind.find(p => p.kind === k);

  // Labeled-universe precision (audit retrieval-cats-04): unlabeled base-page
  // links stay OUT of the denominator; a flawless extractor scores 1.0.
  const overallP = ratio(totalMatched, totalMatched + totalMistyped + totalFp);
  const overallR = ratio(totalMatched, totalMust);

  const overall: Cat6Report['overall'] = {
    link_precision: overallP,
    link_recall: overallR,
    link_f1: f1(overallP, overallR),
    code_fence_leak_rate: kindReport('code_fence_leak')?.false_positive_rate ?? null,
    inline_code_leak_rate: kindReport('inline_code_slug')?.false_positive_rate ?? null,
    substring_fp_rate: kindReport('substring_collision')?.false_positive_rate ?? null,
    ambiguous_role_type_match_rate: kindReport('ambiguous_role')?.type_match_rate ?? null,
    pages_with_links_coverage: variants.length === 0 ? 0 : variantsWithLinks / variants.length,
    mean_links_per_page: variants.length === 0 ? 0 : totalExtracted / variants.length,
  };

  const gates = evaluateGates(overall);

  return {
    schema_version: 2,
    ran_at: new Date().toISOString(),
    variants: variants.length,
    corpus_id: '',
    per_kind,
    kinds_not_exercised: [...KINDS_NOT_EXERCISED],
    overall,
    gates,
    negative_controls: [],
    verdict: gates.every(g => g.pass) ? 'pass' : 'fail',
    rows: variants.map((variant, i) => variantEvidence(variant, results[i])),
  };
}

// ─── Runner entry ─────────────────────────────────────────────────────

export interface RunCat6Options {
  corpusDir?: string;
  perKind?: number;
  baseSeed?: number;
}

export interface Cat6RunOutcome {
  report: Cat6Report;
  accounting: ProbeSummary;
  /** Negative controls that did NOT fire — the metric cannot fail; run invalid. */
  control_failures: string[];
}

export async function runCat6(
  opts: RunCat6Options = {},
  rows: VariantEvidenceRow[] = [],
  extractor: typeof extractOne = extractOne,
): Promise<Cat6RunOutcome> {
  const corpusDir = opts.corpusDir ?? resolve(process.cwd(), 'eval/data/world-v1');
  const pages = loadWorldV1(corpusDir);
  const variants = generateVariants(pages, {
    perKind: opts.perKind,
    baseSeed: opts.baseSeed,
  });
  const resolver = makeCorpusResolver(pages);
  const acc = new ProbeAccounting(variants.length);

  const results: VariantResult[] = [];
  for (const v of variants) {
    let extracted: ExtractedLink[] | null = null;
    try {
      extracted = await extractor(v, resolver);
    } catch (err) {
      // The SUT (gbrain's extractor) threw on valid content: scored miss —
      // every must_extract counts missed, and the probe scores 0.
      const msg = String(err);
      acc.error(v.variantId, 'sut', msg);
      const result = {
        ...scoreExtraction(v, []),
        sut_error: msg,
      };
      results.push(result);
      rows.push(variantEvidence(v, result));
      continue;
    }
    const r = scoreExtraction(v, extracted);
    results.push(r);
    rows.push(variantEvidence(v, r));
    const clean = r.missed.length + r.mistyped.length + r.false_positives.length === 0;
    acc.score(v.variantId, clean ? 1 : 0);
  }

  const report = aggregate(variants, results);
  report.corpus_id = basename(corpusDir);
  report.negative_controls = runNegativeControls(variants);
  const control_failures = report.negative_controls
    .filter(c => !c.fired)
    .map(c => c.control);

  return { report, accounting: acc.summary(), control_failures };
}

// ─── Gazetteer arm (bare-prose-name linking through by-mention) ───────

export interface GazetteerArmRow {
  variant_id: string;
  page_slug: string;
  target_slug: string;
  /** Link types found from the variant page to the target after the by-mention pass. */
  link_types: string[];
  /** Same, after only the ordinary links pass (control). */
  default_pass_link_types: string[];
}

export interface GazetteerArmReport {
  entry_point: string;
  variants: number;
  matched: number;
  mistyped: number;
  missed: number;
  recall: number | null;
  type_match_rate: number | null;
  /** Recall of the ordinary links pass (no gazetteer) on the same variants. */
  default_pass_recall: number | null;
  /** by-mention links from variant pages to entities the gold does not label. Diagnostic only. */
  unlabeled_mention_links: number;
  gates: GateResult[];
  rows: GazetteerArmRow[];
}

const GAZETTEER_PAGE_PREFIX = 'notes/cat6-prose-only-';

function frontmatterPage(type: string, title: string, body: string): string {
  return `---\ntype: ${type}\ntitle: ${JSON.stringify(title)}\n---\n\n${body}\n`;
}

/**
 * Score prose_only_mention through gbrain's by-mention pass. Imports every
 * person/company page (the gazetteer's source) and each variant as its own
 * note page into a fresh in-memory PGLite brain, runs the ordinary links
 * pass (control), then the by-mention pass, and reads links back.
 */
export async function runGazetteerArm(
  pages: BasePage[],
  opts: { perKind?: number; baseSeed?: number } = {},
): Promise<GazetteerArmReport> {
  const variants = generateVariants(pages, { perKind: opts.perKind, baseSeed: opts.baseSeed, kinds: ['prose_only_mention'] });
  const { PGLiteEngine } = await import('gbrain/pglite-engine');
  const { importFromContent } = await import('gbrain/import-file');
  const { runExtract } = await import('gbrain/extract');
  const engine: any = new PGLiteEngine();
  const origLog = console.log;
  console.log = () => {};
  const linksFrom = async () => await engine.executeRaw(
    `SELECT f.slug AS from_slug, t.slug AS to_slug, l.link_type FROM links l
       JOIN pages f ON f.id = l.from_page_id JOIN pages t ON t.id = l.to_page_id
      WHERE f.slug LIKE $1`,
    [`${GAZETTEER_PAGE_PREFIX}%`],
  ) as Array<{ from_slug: string; to_slug: string; link_type: string }>;
  let defaultLinks: Array<{ from_slug: string; to_slug: string; link_type: string }>;
  let mentionLinks: Array<{ from_slug: string; to_slug: string; link_type: string }>;
  const pageSlugs = variants.map((_, i) => `${GAZETTEER_PAGE_PREFIX}${String(i).padStart(3, '0')}`);
  try {
    await engine.connect({});
    await engine.initSchema();
    for (const p of pages.filter(p => p.type === 'person' || p.type === 'company')) {
      await importFromContent(engine, p.slug, frontmatterPage(p.type, p.title, p.content), { noEmbed: true });
    }
    for (const [i, v] of variants.entries()) {
      await importFromContent(engine, pageSlugs[i], frontmatterPage('note', `Prose variant ${i}`, v.content), { noEmbed: true });
    }
    await runExtract(engine, ['links', '--source', 'db']);
    defaultLinks = await linksFrom();
    await runExtract(engine, ['links', '--by-mention', '--source', 'db']);
    mentionLinks = (await linksFrom()).filter(l => !defaultLinks.some(d => d.from_slug === l.from_slug && d.to_slug === l.to_slug && d.link_type === l.link_type));
  } finally {
    console.log = origLog;
    try { await engine.disconnect(); } catch { /* already closed */ }
  }
  const rows: GazetteerArmRow[] = variants.map((v, i) => {
    const target = v.goldDelta.must_extract[0]!.slug;
    const typesIn = (links: typeof defaultLinks) => [...new Set(links.filter(l => l.from_slug === pageSlugs[i] && l.to_slug === target).map(l => l.link_type))].sort();
    return { variant_id: v.variantId, page_slug: pageSlugs[i]!, target_slug: target, link_types: typesIn(mentionLinks), default_pass_link_types: typesIn(defaultLinks) };
  });
  const matched = rows.filter(r => r.link_types.includes('mentions')).length;
  const mistyped = rows.filter(r => r.link_types.length > 0 && !r.link_types.includes('mentions')).length;
  const labeled = new Set(rows.map(r => `${r.page_slug}>${r.target_slug}`));
  const recall = ratio(matched + mistyped, rows.length);
  const typeMatch = ratio(matched, matched + mistyped);
  const gates: GateResult[] = [
    { gate: 'prose_only_mention_gazetteer_recall_min', value: recall, bound: GAZETTEER_GATES.prose_only_mention_gazetteer_recall_min, op: 'min', pass: recall !== null && recall >= GAZETTEER_GATES.prose_only_mention_gazetteer_recall_min },
    { gate: 'prose_only_mention_gazetteer_type_match_min', value: typeMatch, bound: GAZETTEER_GATES.prose_only_mention_gazetteer_type_match_min, op: 'min', pass: typeMatch !== null && typeMatch >= GAZETTEER_GATES.prose_only_mention_gazetteer_type_match_min },
  ];
  return {
    entry_point: "runExtract(engine, ['links', '--by-mention', '--source', 'db']) after ['links', '--source', 'db']",
    variants: rows.length,
    matched,
    mistyped,
    missed: rows.length - matched - mistyped,
    recall,
    type_match_rate: typeMatch,
    default_pass_recall: ratio(rows.filter(r => r.default_pass_link_types.length > 0).length, rows.length),
    unlabeled_mention_links: mentionLinks.filter(l => !labeled.has(`${l.from_slug}>${l.to_slug}`)).length,
    gates,
    rows,
  };
}

// ─── CLI ──────────────────────────────────────────────────────────────

interface CliOpts {
  corpusDir?: string;
  perKind?: number;
  baseSeed?: number;
  allowSkip: boolean;
  receiptPathOverride?: string;
  reportPathOverride?: string;
}

function parseArgs(argv: string[]): CliOpts {
  const opts: CliOpts = { allowSkip: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--allow-skip') opts.allowSkip = true;
    else if (a === '--corpus-dir') opts.corpusDir = argv[++i];
    else if (a === '--per-kind') opts.perKind = Number(argv[++i]);
    else if (a === '--base-seed') opts.baseSeed = Number(argv[++i]);
    else if (a === '--receipt-path') opts.receiptPathOverride = argv[++i];
    else if (a === '--report-path') opts.reportPathOverride = argv[++i];
    else throw new Error(`unknown arg: ${a}`);
  }
  return opts;
}

export async function main(argv: string[] = process.argv.slice(2)): Promise<number> {
  const cli = parseArgs(argv);
  const startedAt = new Date().toISOString();
  const receiptFile = cli.receiptPathOverride ?? receiptPath('cat6-prose-scale');
  const reportFile = cli.reportPathOverride
    ?? join(process.cwd(), 'eval/reports/cat6-prose-scale/report.json');
  const corpusDir = cli.corpusDir ?? resolve(process.cwd(), 'eval/data/world-v1');

  const receiptBase = {
    schema_version: RECEIPT_SCHEMA_VERSION,
    benchmark_version: BENCHMARK_VERSION,
    category: 'cat6-prose-scale',
    gbrain_version: gbrainVersion(),
    gbrain_pin: gbrainPin(),
    started_at: startedAt,
  } as const;

  if (!existsSync(corpusDir)) {
    const reason = `corpus dir not found: ${corpusDir} — world-v1 ships with the repo; a missing dir means a broken checkout.`;
    writeReceipt(receiptFile, {
      ...receiptBase,
      run_status: 'skipped',
      skip_reason: reason,
      n_total: 0,
      n_scored: 0,
      completion_rate: 0,
      errors: [],
      publishable: false,
      finished_at: new Date().toISOString(),
    });
    console.error(`[cat6] SKIPPED — ${reason} ${cli.allowSkip ? '--allow-skip acknowledged.' : 'Exiting non-zero (pass --allow-skip to acknowledge).'}`);
    return cli.allowSkip ? 0 : 2;
  }

  let outcome: Cat6RunOutcome;
  const rows: VariantEvidenceRow[] = [];
  try {
    outcome = await runCat6({
      corpusDir,
      perKind: cli.perKind,
      baseSeed: cli.baseSeed,
    }, rows);
  } catch (err) {
    // Corpus/aggregation failure before scoring completed: our bug, not the SUT's.
    writeReceipt(receiptFile, {
      ...receiptBase,
      run_status: 'error',
      n_total: 0,
      n_scored: 0,
      completion_rate: 0,
      errors: [{ probe_id: 'run', origin: 'harness', message: String(err) }],
      publishable: false,
      finished_at: new Date().toISOString(),
      data: { rows: rows.map(row => ({ ...row, contributed: false })) },
    });
    console.error(`[cat6] HARNESS ERROR — ${String(err)}`);
    return 3;
  }

  const { report, accounting, control_failures } = outcome;
  let gazetteer: GazetteerArmReport | null = null;
  let gazetteerError: string | null = null;
  try {
    gazetteer = await runGazetteerArm(loadWorldV1(corpusDir), { perKind: cli.perKind, baseSeed: cli.baseSeed });
  } catch (err) {
    gazetteerError = String(err);
  }
  const verdict: 'pass' | 'fail' = report.verdict === 'pass' && gazetteer !== null && gazetteer.gates.every(g => g.pass) ? 'pass' : 'fail';

  mkdirSync(dirname(reportFile), { recursive: true });
  writeFileSync(reportFile, JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify(report, null, 2));

  const base = {
    ...receiptBase,
    ...noModelSpend('hermetic: no model and no paid request (pure extractor and in-memory PGLite by-mention pass)'),
    n_total: accounting.n_total,
    n_scored: accounting.n_scored,
    completion_rate: accounting.completion_rate,
    errors: accounting.errors,
    resolved_config: {
      corpus_dir: corpusDir,
      corpus_id: report.corpus_id,
      per_kind: cli.perKind ?? 50,
      base_seed: cli.baseSeed ?? 1000,
      kinds_scored: [...SCORED_INJECTION_KINDS],
      kinds_not_exercised: [...KINDS_NOT_EXERCISED],
      gates: GATES,
      gazetteer_gates: GAZETTEER_GATES,
      extraction_path: 'extractPageLinks (gbrain/link-extraction), frontmatter {}, no LLM/DB',
      gazetteer_arm_path: gazetteer?.entry_point ?? "runExtract(engine, ['links', '--by-mention', '--source', 'db'])",
    },
    finished_at: new Date().toISOString(),
    data: {
      overall: report.overall,
      per_kind: Object.fromEntries(report.per_kind.map(p => [p.kind, {
        precision: p.precision,
        recall: p.recall,
        type_match_rate: p.type_match_rate,
        false_positive_rate: p.false_positive_rate,
      }])),
      gates: [...report.gates, ...(gazetteer?.gates ?? [])],
      negative_controls: report.negative_controls,
      gazetteer_arm: gazetteer,
      rows: report.rows,
    },
  };

  if (variantsEmpty(report)) {
    const reason = `corpus at ${corpusDir} produced 0 variants (no person/company pages).`;
    writeReceipt(receiptFile, {
      ...base,
      run_status: 'skipped',
      skip_reason: reason,
      publishable: false,
    });
    console.error(`[cat6] SKIPPED — ${reason} ${cli.allowSkip ? '--allow-skip acknowledged.' : 'Exiting non-zero (pass --allow-skip to acknowledge).'}`);
    return cli.allowSkip ? 0 : 2;
  }

  if (control_failures.length > 0 || accounting.run_invalid) {
    const controlErrors = control_failures.map(c => ({
      probe_id: `negative-control:${c}`,
      origin: 'harness' as const,
      message: 'simulated-bug extraction produced zero scored false positives — the metric cannot fail; run invalid',
    }));
    writeReceipt(receiptFile, {
      ...base,
      errors: [...accounting.errors, ...controlErrors],
      run_status: 'error',
      publishable: false,
    });
    console.error(`[cat6] RUN INVALID —${accounting.run_invalid ? ` infra error rate ${(accounting.infra_error_rate * 100).toFixed(1)}% over cap.` : ''}${control_failures.length > 0 ? ` negative control(s) did not fire: ${control_failures.join(', ')}` : ''}`);
    return 3;
  }

  if (gazetteerError !== null) {
    writeReceipt(receiptFile, {
      ...base,
      errors: [...accounting.errors, { probe_id: 'gazetteer-arm', origin: 'sut', message: gazetteerError }],
      run_status: 'completed',
      verdict: 'fail',
      publishable: false,
    });
    console.error(`[cat6] gazetteer arm failed — ${gazetteerError}`);
    return 1;
  }

  writeReceipt(receiptFile, {
    ...base,
    run_status: 'completed',
    verdict,
    publishable: accounting.publishable,
  });
  const failing = [...report.gates, ...gazetteer!.gates].filter(g => !g.pass).map(g => g.gate);
  console.error(`[cat6] verdict=${verdict}${failing.length > 0 ? ` (failing gates: ${failing.join(', ')})` : ''} — ${report.variants} variants, recall=${fmt(report.overall.link_recall)}, precision=${fmt(report.overall.link_precision)}, type_match=${fmt(report.overall.ambiguous_role_type_match_rate)}; gazetteer arm ${gazetteer!.matched}/${gazetteer!.variants} prose-only mentions linked (ordinary pass ${fmt(gazetteer!.default_pass_recall)})`);
  return verdict === 'pass' ? 0 : 1;
}

function variantsEmpty(report: Cat6Report): boolean {
  return report.variants === 0;
}

function fmt(v: number | null): string {
  return v === null ? 'n/a' : v.toFixed(3);
}

if (import.meta.main) {
  main()
    .then(code => process.exit(code))
    .catch(err => {
      console.error(err);
      process.exit(3);
    });
}
